export interface CatalogObject {
  slug: string;
  name: string;
  category: string;
  description: string;
  asset?: string;
  primitive?: 'ground' | 'zone' | 'path';
  color?: string;
  colorLabel?: string;
  variants?: readonly string[];
  states?: readonly VisualState[];
  animation: 'none' | 'local';
  /** Explicit physical property shown by the isolated preview, independent of State. */
  operatingProperty?: 'heatEnabled' | 'waterRunning' | 'fillLevel';
  countDefinition?: AssetCountDefinition;
  measurement?: Readonly<Measurement>;
  display?: Readonly<DisplayReading>;
  /** Sized surfaces: width × depth range and defaults. */
  footprint?: FootprintDefinition;
  /** Default base tone per variant. Color is exported only after the user changes it, so each finish keeps its own tone. */
  variantColors?: Readonly<Record<string, string>>;
  guide: string;
  /** Optional runnable composition route; absent when only the isolated catalog preview is available. */
  example?: string;
  notes: string;
}
