export const catalogCategories = ['All objects', ...new Set(catalogObjects.map(item => item.category))];
/** User-facing activity names; a host must supply these facts rather than infer them from motion. */
export function catalogStateLabel(item: CatalogObject, state: VisualState): string {
  if (item.asset === 'status-beacon') return ({ normal: 'Normal (green)', busy: 'Normal (green)', warning: 'Warning (amber)', critical: 'Critical (red)', inactive: 'Inactive (off)' })[state];
  if (state === 'busy') return ({ 'battery-indicator': 'Charging', 'mobile-robot': 'Assigned / working', 'ev-charger': 'Charging' } as Record<string, string>)[item.asset ?? ''] ?? 'Busy';
  return state[0].toUpperCase() + state.slice(1);
}
export function objectNode(item: CatalogObject, options: { localMotion?: boolean; heatEnabled?: boolean; waterRunning?: boolean; fillLevel?: number; person?: PersonOptions; materials?: MaterialOverrides; footprint?: Footprint; display?: DisplayReading; building?: BuildingOptions; color?: string; variant?: string; state?: VisualState; rotation?: Vec3; scale?: number; x?: number; count?: number; multiplier?: number; countLayout?: CountLayout; surfaceLabel?: SurfaceLabel; measurement?: Measurement | false } = {}): SceneNode {
  const base = { id: 'catalog-object', selectable: true, position: [options.x ?? 0, 0, 0] as const, ...(options.rotation ? { rotation: options.rotation } : {}), ...(options.scale === undefined ? {} : { scale: [options.scale, options.scale, options.scale] as const }), ...(options.state === undefined ? {} : { state: options.state }) };
  if (item.primitive === 'ground' || item.primitive === 'zone') return { ...base, kind: item.primitive, size: [6, 5], color: options.color ?? item.color };
  if (item.primitive === 'path') return { ...base, kind: 'path', points: [[-3, 0, 1], [0, 0, 1], [2, 0, -2]], color: options.color ?? item.color };
  if (!item.asset) throw new Error(`No portable definition for ${item.slug}.`);
  if (item.asset === 'building') return { ...base, kind: 'asset', asset: 'building', ...(options.color ? { color: options.color } : {}), ...(options.materials ? { materials: options.materials } : {}), building: { view: 'closed', ...options.building, type: options.building?.type ?? (options.variant as BuildingType | undefined) ?? 'generic' } };
  const measurement = options.measurement === false ? undefined : options.measurement ?? item.measurement;
  const representation = item.countDefinition && !measurement ? resolveCountRepresentation(options, item.countDefinition) : undefined;
  return { ...base, kind: 'asset', asset: item.asset, ...(options.localMotion === undefined ? {} : { localMotion: options.localMotion }), ...(options.heatEnabled === undefined ? {} : { heatEnabled: options.heatEnabled }), ...(options.waterRunning === undefined ? {} : { waterRunning: options.waterRunning }), ...(options.fillLevel === undefined ? {} : { fillLevel: options.fillLevel }), ...(options.display ?? item.display ? { display: options.display ?? item.display } : {}), ...(item.variantColors ? options.color ? { color: options.color } : {} : { color: options.color ?? item.color }), variant: options.variant ?? item.variants?.[0], ...(options.footprint && item.footprint ? { footprint: options.footprint } : {}), ...(options.person && isPersonAsset(item.asset) ? { person: options.person } : {}), ...(options.materials ? { materials: options.materials } : {}), ...(options.surfaceLabel && assetLabelSurfaces[item.asset] ? { surfaceLabel: options.surfaceLabel } : {}), ...(measurement ? { measurement } : {}), ...(!measurement && assetCountLayoutDefaults[item.asset] ? { countLayout: options.countLayout ?? 'reserved' } : {}), ...(representation ? { count: representation.count, ...(options.multiplier === undefined ? {} : { multiplier: representation.multiplier }), label: options.multiplier === undefined ? `${representation.count} ${item.countDefinition!.unit}` : `${representation.total.toLocaleString('en-US')} ${item.countDefinition!.unit} · ${representation.count} × ${representation.multiplier.toLocaleString('en-US')}` } : {}) };
}

/** Object browser category → `@opsorama/objects` kit subpath; tests/catalog-kits.test.ts keeps both in step. */
const CATALOG_KIT_BY_CATEGORY: Readonly<Record<string, CatalogKit>> = { "Datacenter / IT": "datacenter", "Displays & time": "displays", "Buildings": "buildings", "Indicators": "indicators", "Work items": "work-items", "People": "people", "Furniture": "furniture", "Equipment": "equipment", "Office": "office", "Retail": "retail", "Fulfillment": "fulfillment", "Vehicles": "vehicles", "Environment": "environment", "Surfaces": "surfaces", "Energy": "energy", "Events": "events", "Restaurant": "restaurant", "Aquatics": "aquatics", "Animals": "animals", "Farm": "farm", "Laboratory": "laboratory" };
/** The kit that contains an asset, for import snippets. */
export function objectKit(asset: string): CatalogKit | undefined { const item = catalogObjects.find(entry => entry.asset === asset); return item ? CATALOG_KIT_BY_CATEGORY[item.category] : undefined; }
const kitExport = (kit: CatalogKit) => kit.replace(/-([a-z])/g, (_, letter: string) => letter.toUpperCase()) + 'Kit';

export function objectSnippet(node: SceneNode, framework: 'React' | 'Vue' | 'JavaScript'): string {
  const { id, kind, ...props } = node;
  const kit = node.kind === 'asset' ? objectKit(node.asset) : undefined;
  const assets = kit ? kitExport(kit) : 'catalogAssets';
  const assetsImport = kit ? `import { ${assets} } from '@opsorama/objects/${kit}';` : `import { catalogAssets } from '@opsorama/objects';`;
  if (framework === 'JavaScript') return `import { createSceneStore } from '@opsorama/core';\nimport { createSceneRenderer } from '@opsorama/three';\n${assetsImport}\n\nconst store = createSceneStore({ schemaVersion: 1, nodes: [\n  ${JSON.stringify(node, null, 2).replace(/\n/g, '\n  ')}\n] });\nconst view = createSceneRenderer(container, store, { assets: ${assets} });\n// On unmount: view.dispose(); store.dispose();`;
  const component = kind[0].toUpperCase() + kind.slice(1);
  const escapeAttribute = (value: string) => value.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const attributes = Object.entries(props).filter(([, value]) => value !== undefined).map(([key, value]) => framework === 'React' ? `${key}=${typeof value === 'string' && !/["\\\n]/.test(value) ? JSON.stringify(value) : `{${JSON.stringify(value)}}`}` : key === 'surfaceLabel' ? ':surfaceLabel="surfaceLabel"' : `${typeof value === 'string' ? key : `:${key}`}="${escapeAttribute(typeof value === 'string' ? value : JSON.stringify(value))}"`).join('\n  ');
  if (framework === 'Vue') return `<script setup lang="ts">\nimport { ${component} } from '@opsorama/vue';\n${assetsImport}${node.kind === 'asset' && node.surfaceLabel ? `\nimport type { SurfaceLabel } from '@opsorama/core';\nconst surfaceLabel: SurfaceLabel = ${JSON.stringify(node.surfaceLabel, null, 2).replace(/</g, '\\u003c')};` : ''}\n</script>\n\n<template>\n  <!-- Inside DashboardProvider and <SceneCanvas :assets="${assets}"> -->\n  <${component} id="${id}"\n    ${attributes.replace(/\n/g, '\n  ')}\n  />\n</template>`;
  return `import { ${component} } from '@opsorama/react';\n${assetsImport}\n\n// Inside DashboardProvider and <SceneCanvas assets={${assets}}>\n<${component} id="${id}"\n  ${attributes}\n/>`;
}
